"""MCP server connection utilities."""

import asyncio
import warnings
from typing import Any, ClassVar, Dict, List, Optional

import structlog
from httpx import HTTPStatusError
from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

from rasa.shared.agents.auth.agent_auth_manager import AgentAuthManager
from rasa.shared.agents.auth.auth_strategy import AgentAuthStrategy
from rasa.shared.exceptions import AuthenticationError

structlogger = structlog.get_logger()


# Suppress RuntimeWarning about unawaited coroutines when MCP server is not reachable.
warnings.filterwarnings(
    "ignore",
    message=".*BaseEventLoop.create_server.*was never awaited.*",
    category=RuntimeWarning,
)


class MCPServerConnection:
    """Manages connection to an MCP server, with optional authentication.

    This class handles:
    - Connection establishment and cleanup
    - Session lifecycle management
    - Authentication via AgentAuthManager (API Key, OAuth2, mTLS, etc.)

    The entire context-manager chain (streamablehttp_client → ClientSession) is
    owned by a single dedicated asyncio.Task (_lifecycle_task).  This prevents
    the anyio cross-task cancel-scope violation (SWI-1287): anyio cancel scopes
    are task-local, so the task that enters them must also exit them.  External
    tasks signal shutdown and await the lifecycle task rather than closing
    context managers directly.
    """

    # Timeout for ping operations in seconds
    PING_TIMEOUT_SECONDS = 3.0

    _SUPPORTED_SERVER_TYPES: ClassVar[List[str]] = ["http", "https"]

    def __init__(
        self,
        server_name: str,
        server_url: str,
        server_type: str,
        auth_manager: Optional[AgentAuthManager] = None,
    ):
        """Initialize the MCP server connection.

        Args:
            server_name: Server name to identify the server
            server_url: Server URL
            server_type: Server type (currently only 'http' is supported)
            auth_manager: Optional AgentAuthManager instance for this connection
        """
        self.server_name = server_name
        self.server_url = server_url
        self.server_type = server_type
        self._auth_manager = auth_manager
        self.session: Optional[ClientSession] = None
        # Lifecycle task owns the anyio context managers for the connection.
        self._lifecycle_task: Optional["asyncio.Task[None]"] = None
        self._session_ready: Optional[asyncio.Event] = None
        self._shutdown: Optional[asyncio.Event] = None
        self._connect_error: Optional[BaseException] = None

    @classmethod
    def from_config(cls, server_config: Dict[str, Any]) -> "MCPServerConnection":
        """Initialize the MCP server connection from a configuration dictionary."""
        auth_config = server_config.get("additional_params")
        _auth_manager = AgentAuthManager.load_auth(auth_config)
        return cls(
            server_config["name"],
            server_config["url"],
            server_config.get("type", "http"),
            _auth_manager,
        )

    async def _run_lifecycle(self, auth_strategy: Optional[AgentAuthStrategy]) -> None:
        """Run the full connection lifecycle in a single asyncio task.

        This task owns the anyio cancel scopes inside streamablehttp_client and
        ClientSession.  It signals _session_ready once the session is available,
        then waits for _shutdown before exiting the context managers.  Because
        enter and exit always happen in this one task the anyio cross-task
        cancel-scope violation (SWI-1287) cannot occur.
        """
        try:
            async with streamablehttp_client(self.server_url, auth=auth_strategy) as (
                read_stream,
                write_stream,
                _,
            ):
                async with ClientSession(read_stream, write_stream) as session:
                    await session.initialize()
                    self.session = session
                    assert self._session_ready is not None
                    self._session_ready.set()
                    assert self._shutdown is not None
                    await self._shutdown.wait()
        except BaseException as exc:
            if self._session_ready is not None and not self._session_ready.is_set():
                # Connection-time error: store for connect() to classify and raise,
                # then signal _session_ready so connect() can unblock and handle it.
                self._connect_error = exc
                self._session_ready.set()
            else:
                # Cleanup-time error (after session was established): re-raise so
                # _cleanup()'s await sees it and logs it at warning level.
                raise

    async def connect(self) -> None:
        """Establish connection to the MCP server.

        Raises:
            ValueError: If the server type is not supported.
            ConnectionError: If connection fails.
            AuthenticationError: If authentication fails.
        """
        if self.server_type not in self._SUPPORTED_SERVER_TYPES:
            raise ValueError(f"Unsupported server type: {self.server_type}")

        self._session_ready = asyncio.Event()
        self._shutdown = asyncio.Event()
        self._connect_error = None

        auth_strategy = self._auth_manager.get_auth() if self._auth_manager else None

        self._lifecycle_task = asyncio.create_task(
            self._run_lifecycle(auth_strategy),
            name=f"mcp-connection-{self.server_name}",
        )

        try:
            await self._session_ready.wait()
        except asyncio.CancelledError as e:
            event_info = f"Connection to MCP server `{self.server_name}` was cancelled."
            structlogger.error(
                "mcp_server_connection.connect.connection_cancelled",
                event_info=event_info,
                server_name=self.server_name,
                server_url=self.server_url,
            )
            await self._cleanup()
            raise ConnectionError(e) from e

        if self._connect_error is not None:
            eg = self._connect_error
            await self._cleanup()
            exc: BaseException = eg
            for exc in getattr(eg, "exceptions", [eg]):
                event_info = (
                    f"Failed to connect to MCP server `{self.server_name}`. \nOriginal "
                    f"error: {exc!s}"
                )
                if isinstance(exc, HTTPStatusError):
                    status_code = exc.response.status_code
                    structlogger.error(
                        "mcp_server_connection.connect.http_status_error",
                        event_info=event_info,
                        server_name=self.server_name,
                        server_url=self.server_url,
                        status_code=status_code,
                        response_text=exc.response.reason_phrase,
                    )
                    if status_code in [400, 401, 403]:
                        raise AuthenticationError(str(exc)) from eg
                    elif status_code == 404:
                        raise Exception(str(exc)) from eg
                    else:
                        raise ConnectionError(str(exc)) from eg
                else:
                    structlogger.error(
                        "mcp_server_connection.connect.other_exception",
                        event_info=event_info,
                        server_name=self.server_name,
                        server_url=self.server_url,
                        error=str(exc),
                    )
            raise ConnectionError(str(exc)) from eg

    async def ensure_active_session(self) -> ClientSession:
        """Ensure an active session is available.

        If no session exists or the current session is inactive,
        a new connection will be established.

        Returns:
            Active ClientSession instance.
        """
        if self.session is None:
            await self.connect()
            structlogger.info(
                "mcp_server_connection.ensure_active_session.no_session",
                server_name=self.server_name,
                server_url=self.server_url,
                event_info=(
                    "No session found, connecting to the server "
                    f"`{self.server_name}` @ `{self.server_url}`"
                ),
            )
        if self.session:
            try:
                # Add timeout to prevent hanging when MCP server is down
                await asyncio.wait_for(
                    self.session.send_ping(), timeout=self.PING_TIMEOUT_SECONDS
                )
            except asyncio.TimeoutError as e:
                structlogger.error(
                    "mcp_server_connection.ensure_active_session.ping_timeout",
                    server_name=self.server_name,
                    server_url=self.server_url,
                    event_info=(
                        "Ping timed out, Server not reachable - "
                        f"`{self.server_name}` @ `{self.server_url}`"
                    ),
                )
                raise e
            except Exception as e:
                structlogger.warning(
                    "mcp_server_connection.ensure_active_session.ping_failed",
                    error=str(e),
                    server_name=self.server_name,
                    server_url=self.server_url,
                    event_info=(
                        "Ping failed, trying to reconnect to the server "
                        f"`{self.server_name}` @ `{self.server_url}`"
                    ),
                )
                # Cleanup existing session
                await self.close()
                # Attempt to reconnect now
                await self.connect()
                structlogger.info(
                    "mcp_server_connection.ensure_active_session.reconnected",
                    server_name=self.server_name,
                    server_url=self.server_url,
                    event_info=(
                        "Reconnected to the server "
                        f"`{self.server_name}` @ `{self.server_url}`"
                    ),
                )
        assert self.session is not None  # Ensures type for mypy
        return self.session

    async def close(self) -> None:
        """Close the connection and clean up resources."""
        await self._cleanup()

    async def _cleanup(self) -> None:
        """Signal the lifecycle task to exit its context managers and await it.

        Because the lifecycle task owns the anyio cancel scopes, signalling it
        here (rather than calling aclose() directly) ensures that context
        manager exit always happens in the task that entered them.  This method
        is task-boundary-safe and may be called from any asyncio task.
        """
        if self._shutdown is not None:
            self._shutdown.set()

        if self._lifecycle_task is not None:
            try:
                await self._lifecycle_task
            except asyncio.CancelledError:
                structlogger.debug(
                    "mcp_server_connection.cleanup.cancelled",
                    server_name=self.server_name,
                    event_info=(
                        f"Cleanup cancelled for {self.server_name} - this is expected "
                        f"during shutdown"
                    ),
                )
            except Exception as e:
                structlogger.warning(
                    "mcp_server_connection.cleanup.failed",
                    server_name=self.server_name,
                    error=str(e),
                )

        self._lifecycle_task = None
        self._session_ready = None
        self._shutdown = None
        self._connect_error = None
        self.session = None
